-- Lo que necesitan las funciones que se trajeron de MS Motos: roles propios, bloqueos de
-- agenda, feriados, servicios por cita, órdenes eliminadas, sesiones por dispositivo,
-- bitácoras de seguridad y registro de respaldos. Todo por empresa desde el principio:
-- cada tabla lleva tenant_id sin valor por defecto, para que una fila sin empresa falle
-- al escribirse en vez de caer en silencio en otra. Va en TABLAS_CON_TENANT (tenant-db.js).

CREATE TABLE "roles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "clave" varchar(30) DEFAULT NULL,
  "nombre" varchar(60) NOT NULL,
  "base" varchar(14) NOT NULL CHECK ("base" IN ('administracion','mostrador','taller','web')),
  "descripcion" varchar(200) DEFAULT NULL,
  "permisos" text DEFAULT NULL,
  "de_fabrica" smallint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_roles_tenant_clave" UNIQUE ("tenant_id", "clave")
);
CREATE TRIGGER "roles_tocar_updated_at" BEFORE UPDATE ON "roles"
  FOR EACH ROW EXECUTE FUNCTION motiq_tocar_updated_at();

-- Cada empresa que ya existe recibe su copia de los roles de fábrica; las nuevas, al
-- registrarse (utils/onboarding.js). Es una copia, no una referencia: lo que ajuste una
-- no le llega a otra.
INSERT INTO "roles" ("tenant_id", "clave", "nombre", "base", "descripcion", "permisos", "de_fabrica")
SELECT t."id", f.clave, f.nombre, f.base, f.descripcion, f.permisos, 1
  FROM "tenants" t CROSS JOIN (VALUES
  ('admin', 'Administrador', 'administracion', 'El dueño: puede todo y ve las dos sucursales. No se puede cambiar.', '["citas.ver","citas.agendar","citas.cancelar","citas.duracion","citas.bloquear","ordenes.crear","ordenes.editar","ordenes.eliminar","ordenes.asignar","ordenes.estado","ordenes.precios","ordenes.costos","ordenes.entregar","ordenes.facturar","clientes.ver","clientes.editar","clientes.eliminar","clientes.portal","taller.trabajar","taller.repuestos","taller.fotos","equipo.mensajes","equipo.tareas","equipo.empleados","analisis.reportes","analisis.opiniones","analisis.promociones","config.taller","config.horarios","config.sucursales","config.entrega","config.notificaciones"]'),
  ('recepcion', 'Recepción', 'mostrador', 'Atiende el mostrador: agenda, recibe motos, arma cotizaciones, entrega y cobra.', '["citas.ver","citas.agendar","citas.cancelar","ordenes.crear","ordenes.editar","ordenes.asignar","ordenes.estado","ordenes.precios","ordenes.costos","ordenes.entregar","ordenes.facturar","clientes.ver","clientes.editar","clientes.eliminar","taller.fotos","equipo.mensajes"]'),
  ('tecnico', 'Mecánico', 'taller', 'Trabaja las órdenes y citas que tiene asignadas. No ve precios.', '["citas.ver","ordenes.estado","taller.trabajar","taller.repuestos","taller.fotos","equipo.mensajes"]'),
  ('contenido', 'Contenido del sitio web', 'web', 'Solo entra a la sección Sitio web, con lo que se le marque a cada persona. No ve nada del taller.', '[]')
  ) AS f(clave, nombre, base, descripcion, permisos);

CREATE TABLE "cita_servicios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "cita_id" integer NOT NULL REFERENCES "citas" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  "servicio" varchar(100) NOT NULL,
  "orden" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_cita_servicios_tenant_cita" ON "cita_servicios" ("tenant_id", "cita_id");

CREATE TABLE "bloqueos_horario" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "sucursal_id" integer DEFAULT NULL,
  "fecha_desde" date NOT NULL,
  "fecha_hasta" date NOT NULL,
  "hora_desde" time DEFAULT NULL,
  "hora_hasta" time DEFAULT NULL,
  "motivo" varchar(150) NOT NULL,
  "creado_por" integer DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_bloqueos_tenant_fechas" ON "bloqueos_horario" ("tenant_id", "fecha_desde", "fecha_hasta");

CREATE TABLE "feriados" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "mes" smallint NOT NULL,
  "dia" smallint NOT NULL,
  "nombre" varchar(80) NOT NULL,
  "sucursal_id" integer DEFAULT NULL,
  "creado_por" integer DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_feriados_tenant" ON "feriados" ("tenant_id", "mes", "dia");

CREATE TABLE "ordenes_eliminadas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "orden_id" integer NOT NULL,
  "numero_orden" varchar(30) NOT NULL,
  "estado" varchar(30) NOT NULL,
  "cliente_id" integer DEFAULT NULL,
  "cliente_nombre" varchar(200) DEFAULT NULL,
  "moto" varchar(200) DEFAULT NULL,
  "problema_reportado" text DEFAULT NULL,
  "total" numeric(10,2) NOT NULL DEFAULT 0,
  "fecha_ingreso" timestamptz DEFAULT NULL,
  "motivo" varchar(500) NOT NULL,
  "eliminada_por" integer DEFAULT NULL,
  "eliminada_por_nombre" varchar(150) DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_ordenes_eliminadas_tenant" ON "ordenes_eliminadas" ("tenant_id", "created_at");

CREATE TABLE "sesiones_personal" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "sid" char(32) NOT NULL,
  "agente" varchar(255) DEFAULT NULL,
  "ip" varchar(64) DEFAULT NULL,
  "creada" timestamptz NOT NULL DEFAULT now(),
  "ultima_vez" timestamptz DEFAULT NULL,
  "vence" timestamptz DEFAULT NULL,
  "cerrada" timestamptz DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_sesiones_sid" UNIQUE ("sid")
);
CREATE INDEX "idx_sesiones_usuario" ON "sesiones_personal" ("usuario_id");

CREATE TABLE "actividad_personal" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "accion" varchar(40) NOT NULL,
  "detalle" varchar(300) DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_actividad_usuario" ON "actividad_personal" ("tenant_id", "usuario_id", "created_at");

-- tenant_id admite NULL solo acá: un intento de entrar con un correo que no existe no
-- pertenece a ninguna empresa.
CREATE TABLE "eventos_seguridad" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer DEFAULT NULL,
  "tipo" varchar(40) NOT NULL,
  "email" varchar(190) DEFAULT NULL,
  "ip" varchar(64) DEFAULT NULL,
  "usuario_id" integer DEFAULT NULL,
  "actor_id" integer DEFAULT NULL,
  "detalle" varchar(300) DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_eventos_created" ON "eventos_seguridad" ("created_at");

-- De la plataforma, no de un taller: el respaldo es de la base entera.
CREATE TABLE "respaldos_registro" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "origen" varchar(10) NOT NULL DEFAULT 'automatico' CHECK ("origen" IN ('automatico','panel')),
  "ok" smallint NOT NULL,
  "clave" varchar(255) DEFAULT NULL,
  "bytes" bigint DEFAULT NULL,
  "tablas" integer DEFAULT NULL,
  "filas" integer DEFAULT NULL,
  "segundos" integer DEFAULT NULL,
  "cifrado" smallint DEFAULT NULL,
  "error" varchar(500) DEFAULT NULL,
  "usuario_id" integer DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

ALTER TABLE "citas"
  ADD COLUMN "metodo_pago" varchar(30) DEFAULT NULL,
  ADD COLUMN "creada_por_orden" smallint NOT NULL DEFAULT 0,
  ADD COLUMN "duracion_horas" smallint NOT NULL DEFAULT 1,
  ADD COLUMN "duracion_min" smallint DEFAULT NULL,
  ADD COLUMN "servicios" varchar(600) DEFAULT NULL;

ALTER TABLE "clientes" ADD COLUMN "google_sub" varchar(64) DEFAULT NULL;
CREATE UNIQUE INDEX "uq_clientes_tenant_google" ON "clientes" ("tenant_id", "google_sub") WHERE "google_sub" IS NOT NULL;

ALTER TABLE "configuracion"
  ADD COLUMN "razon_social" varchar(150) DEFAULT NULL,
  ADD COLUMN "cedula_juridica" varchar(30) DEFAULT NULL,
  ADD COLUMN "nota_factura" varchar(300) DEFAULT NULL,
  ADD COLUMN "pass_min_largo" smallint DEFAULT 8,
  ADD COLUMN "pass_variedad" smallint DEFAULT 0,
  ADD COLUMN "plantillas" text DEFAULT NULL,
  ADD COLUMN "portal_textos" text DEFAULT NULL;

ALTER TABLE "ordenes_trabajo"
  ADD COLUMN "total_aprobado" numeric(10,2) DEFAULT NULL,
  ADD COLUMN "motivo_cancelacion" varchar(300) DEFAULT NULL;

ALTER TABLE "orden_repuestos" ADD COLUMN "adicional" smallint NOT NULL DEFAULT 0;

ALTER TABLE "usuarios"
  ADD COLUMN "rol_id" integer DEFAULT NULL REFERENCES "roles" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE,
  ADD COLUMN "sesiones_desde_ms" bigint DEFAULT NULL,
  ADD COLUMN "ultimo_ingreso" timestamptz DEFAULT NULL,
  ADD COLUMN "preferencias" text DEFAULT NULL,
  ADD COLUMN "firma" text DEFAULT NULL;

-- El checklist era único por orden en TODA la tabla, no por empresa.
ALTER TABLE "orden_checklist" DROP CONSTRAINT "idx_orden_checklist_orden_id";
ALTER TABLE "orden_checklist" ADD CONSTRAINT "uq_checklist_tenant_orden" UNIQUE ("tenant_id", "orden_id");
